element.style.setProperty('--reorder-done', '1');
if (element.getAttribute('data-reordered') === 'true') return;
element.setAttribute('data-reordered', 'true');

const items = Array.from(element.children).filter(li => li.classList.contains('serp-item'));
const englishItems = [];
const russianItems = [];

items.forEach(item => {
  const titleSpan = item.querySelector('.OrganicTitleContentSpan');
  if (!titleSpan) return;

  const text = titleSpan.textContent || '';
  // Check if the title contains mostly Latin characters (English)
  const latinChars = (text.match(/[a-zA-Z]/g) || []).length;
  const cyrillicChars = (text.match(/[а-яА-ЯёЁ]/g) || []).length;

  if (latinChars > cyrillicChars && latinChars > 3) {
    englishItems.push(item);
  } else {
    russianItems.push(item);
  }
});

// Reorder: Russian first, then English at bottom
russianItems.forEach(item => element.appendChild(item));
englishItems.forEach(item => element.appendChild(item));
